    inner();
    console.log(x); // 10
}

function inner() {
    let x = 20;
    console.log(x); // 20
}

outer();
// console.log will output: 
// 10
// 20

// Here, x is first set to 10 in the outer scope, then set to 20 in the inner scope.
// The console.log statements in both functions still have access to these variables,
// even after the inner function has returned.
```

